//! Entry point of the app.
//!
//! The UI lives in TypeScript + TSX: `src/App.tsx` is the root component and
//! `src/components/*.tsx` the business components. `build.rs` compiles them
//! with `zant_build::tsx_app()` into `$OUT_DIR` (`App.rs` and one module per
//! file, plus `main.rs` with their `#[path] mod …;` declarations); the
//! declarations are included below, so `crate::app` is the root component.
//! Do not put UI code in this file.
//!
//! `src/app_config.rs` is generated by `zant` from `app.config.json`
//! (`zant create` / `zant sync`); do not edit it by hand.
//!
//! Native modules are Rust: `native/<name>.ts` is the spec (the single source
//! of truth), `native/<name>.rs` the implementation, `native/lib.rs` the list
//! and registration. `build.rs` also writes the generated `native/spec.rs`
//! (the specs' Rust types and traits, gitignored) that `native/lib.rs` declares
//! as `pub mod spec;`.

// Lints the generated component tree needs (it is included into this crate);
// `zant-build` writes plain items without `#![…]` inner attributes so that
// `include!` accepts the file.
#![allow(clippy::redundant_clone)]
#![allow(clippy::too_many_arguments)]

mod app_config;

// Native modules live next to `src/` (`native/lib.rs`, `native/system.rs`),
// like the TS + TSX convention of the framework.
#[path = "../native/lib.rs"]
mod native;

// The generated modules of `src/**/*.tsx` — `crate::app` for `src/App.tsx`
// and one module per other file. `build.rs` (`zant_build::tsx_app()`) writes
// `main.rs` (the `#[path] mod …;` declarations, resolved relative to that
// file's directory in `$OUT_DIR`) and the modules next to it.
include!(concat!(env!("OUT_DIR"), "/main.rs"));

fn main() -> zant::Result<()> {
    // `src/app_config.rs` also carries the values `zant package` / `zant build`
    // read from `app.config.json` (the version, the macOS sandbox flag and the
    // signing identity). A new app does not use them yet; referencing them here
    // keeps `cargo build` warning-free.
    let _ = (
        app_config::version,
        app_config::sandbox,
        app_config::signing_identity,
    );
    // Native modules register on the UI thread before the first frame.
    native::register();
    zant::tsx::app::run::<crate::app::App>(zant::tsx::app::Config {
        title: app_config::title.to_string(),
        window: app_config::window,
        bundle_id: app_config::bundle_id.to_string(),
        single_instance: app_config::single_instance,
        // Set to true when a component uses `useClipboardChange()`.
        watch_clipboard: false,
    })
}
